package village.vale.arenas;

import com.google.gson.*;
import java.util.*;
import net.minecraft.entity.*;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.*;
import net.minecraftforge.common.*;
import net.minecraftforge.event.entity.living.LivingDeathEvent;
import net.minecraftforge.fml.common.eventhandler.*;

/** Actual native kills test preview, Creative-to-Survival before END, and a
 * genuine official respawn. No mock death, HP/credit assignment or flag bypass. */
public final class GaaraPolicyNegativeNativeChecks {
 private static MinecraftServer server;private static EntityPlayerMP player;private static ArenaDirector.Definition d;private static EntityLivingBase boss;private static JsonObject run,report,row;private static JsonArray rows,failures;private static int variant,stage,wait,ticks,attempts;private static boolean done;private static LivingDeathEvent death;
 private static final Observer observer=new Observer();private static final String[] MODES={"PREVIEW_NATIVE_KILL","CREATIVE_KILL_SWITCHED_TO_SURVIVAL_BEFORE_END","SAME_UUID_OFFICIAL_RESPAWN_BEFORE_END"};
 private GaaraPolicyNegativeNativeChecks(){}
 private static void check(boolean ok,String why){if(!ok)throw new IllegalStateException(why);}
 private static void guide(int[] at){NativeProbe.prewarm(server.getWorld(0),new BlockPos(at[0],at[1],at[2]));ArenaDirector.move(player,at);server.getWorld(0).getPlayerChunkMap().updateMovingPlayer(player);}
 public static void begin(MinecraftServer s,List<ArenaDirector.Definition> defs,EntityPlayerMP p){check(Boolean.getBoolean("hbv.arenas.gaaraOnly")&&Boolean.getBoolean("hbv.arenas.nativeProbe"),"Private native mode guard");server=s;player=p;for(ArenaDirector.Definition value:defs)if(value.boss.equals("narutomod:gaara"))d=value;check(d!=null&&d.native_death_verified,"Production Gaara native policy absent");report=new JsonObject();rows=new JsonArray();failures=new JsonArray();report.add("cases",rows);report.add("failures",failures);report.addProperty("scope","ACTUAL_NATIVE_PREVIEW_CREATIVE_MODE_AND_OFFICIAL_RESPAWN_NEGATIVES; private setup, no normal reward entitlement");variant=stage=wait=ticks=attempts=0;done=false;MinecraftForge.EVENT_BUS.register(observer);}
 private static void defend(){if(boss==null||!boss.isEntityAlive()||!player.isEntityAlive())return;player.rotationYaw=(float)Math.toDegrees(Math.atan2(-(boss.posX-player.posX),boss.posZ-player.posZ));if(!player.isHandActive())player.setActiveHand(EnumHand.OFF_HAND);}
 private static boolean rejectsReward(){try{RewardOutbox.deliver(player,run,0);return false;}catch(IllegalStateException expected){return true;}}
 public static boolean tick(){if(done)return true;defend();check(++ticks<1400,"Bounded negative native fixture exceeded1400ticks");if(--wait>0)return false;try{
  if(variant>=MODES.length){finish();return true;}
  if(stage==0){player.setGameType(GameType.SURVIVAL);for(ArenaDirector.Definition a:ArenaDirector.DEFINITIONS){JsonObject r=ArenaDirector.run(a);check(r==null||!r.getAsJsonObject("members").has(player.getUniqueID().toString()),"Foreign membership preserved");}player.heal(player.getMaxHealth());row=new JsonObject();row.addProperty("mode",MODES[variant]);rows.add(row);check(ArenaIntro.complete(player,d),"Actual intro from normal terminal case missing");int claims=RewardOutbox.receipts(player).getKeySet().size();row.addProperty("receipts_before",claims);server.getCommandManager().executeCommand(player,"narutoarena "+(variant==0?"preview ":"enter ")+d.id);run=ArenaDirector.run(d);check(run!=null&&ArenaDirector.text(run,"state").startsWith("PHASE"),"Actual native negative admission failed");boss=(EntityLivingBase)server.getWorld(0).getEntityFromUuid(UUID.fromString(ArenaDirector.text(run,"boss_uuid")));check(boss!=null,"Actual native body absent");row.addProperty("run_uuid",ArenaDirector.text(run,"run"));row.addProperty("boss_uuid",boss.getUniqueID().toString());row.addProperty("production_native_death_flag",d.native_death_verified);death=null;attempts=0;guide(new int[]{(int)Math.floor(boss.posX)+2,d.floor,(int)Math.floor(boss.posZ)});stage=1;wait=22;return false;}
  if(stage==1){check(attempts++<12,"Original provider rejected bounded negative contacts");if(variant==1)player.setGameType(GameType.CREATIVE);boolean accepted=boss.attackEntityFrom(DamageSource.causePlayerDamage(player),1000F);if(variant==1)player.setGameType(GameType.SURVIVAL);row.addProperty("actual_native_return",accepted);if(boss.isEntityAlive()){wait=22;return false;}check(death!=null&&!death.isCanceled(),"Actual negative native death not accepted");row.addProperty("actual_uncancelled_native_death",true);if(variant==1){check(!ArenaDirector.DEATHS.get(ArenaDirector.text(run,"run")).eligibleAtEvent,"Creative death snapshot was eligible");row.addProperty("actual_creative_at_death_survival_before_end",true);}if(variant==2){ArenaDirector.DeathContact contact=ArenaDirector.DEATHS.get(ArenaDirector.text(run,"run"));check(contact!=null&&contact.eligibleAtEvent,"Normal source snapshot absent before official respawn");EntityPlayerMP old=player;player.attackEntityFrom(DamageSource.OUT_OF_WORLD,1000000F);check(!player.isEntityAlive(),"Genuine private death was rejected");player=server.getPlayerList().recreatePlayerEntity(player,0,false);check(player.isEntityAlive()&&server.getPlayerList().getPlayerByUUID(player.getUniqueID())==player,"Official recreation failed");row.addProperty("same_object_native_recreation",player==old);row.addProperty("source_epoch_at_death",contact.epoch);row.addProperty("source_epoch_after_respawn",ArenaDirector.playerEpoch(player));check(!contact.current(d,run),"Recreated source context remained eligible");row.addProperty("actual_official_respawn_stale_source_rejected",true);}stage=2;wait=variant==0?160:25;return false;}
  if(stage==2){String state=ArenaDirector.text(run,"state");if(variant==0){check(state.equals("PREVIEW_CLEARED"),"Actual preview native ending did not clear distinctly: "+state);check(run.getAsJsonObject("members").getAsJsonObject(player.getUniqueID().toString()).get("contribution").getAsDouble()==0,"Preview native ending earned contribution");}else check(!state.equals("REWARD_PENDING"),"Invalid source obtained native earned terminal");check(rejectsReward(),"Actual invalid native outcome delivered reward");check(RewardOutbox.receipts(player).getKeySet().size()==row.get("receipts_before").getAsInt(),"Invalid native outcome wrote a reward receipt");row.addProperty("actual_earned_claim_rejected",true);row.addProperty("terminal_state",state);server.getCommandManager().executeCommand(player,"narutoarena exit");stage=3;wait=3;return false;}
  if(stage==3){if(!ArenaDirector.text(run,"state").equals("AVAILABLE")){check(ArenaDirector.text(run,"state").equals("RESET_READY"),"Actual negative exit/reset failed");wait=1;return false;}row.addProperty("passed",true);boss=null;run=null;variant++;stage=0;wait=3;return false;}
 }catch(Throwable failure){failures.add(failure.toString());if(row!=null){row.addProperty("failed_stage",stage);row.addProperty("passed",false);}finish();return true;}return false;}
 private static void finish(){MinecraftForge.EVENT_BUS.unregister(observer);report.addProperty("passed",failures.size()==0&&rows.size()==MODES.length);done=true;}
 public static JsonObject result(){return report;}public static EntityPlayerMP currentPlayer(){return player;}
 public static final class Observer {@SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true)public void died(LivingDeathEvent e){if(e.getEntityLiving()==boss)death=e;}}
}
